     * readback is mapped asynchronously and waited for while the JVM side's staging buffer is
     * filled.
     */
    @JvmField val readBuffer: MethodHandle =
        handle("read_buffer", FunctionDescriptor.of(ValueLayout.JAVA_BOOLEAN, PTR, PTR, LONG, LONG, PTR))

