    @JvmField val dropTexture: MethodHandle =
        handle("drop_texture", FunctionDescriptor.ofVoid(PTR))

    /**
     * Creates a sampler with the address modes and filters Blaze3D asked for.
     *
     * The modes travel as the numbers of `com.mojang.blaze3d.textures.AddressMode` (0 `REPEAT`,
     * 1 `CLAMP_TO_EDGE`) and `FilterMode` (0 `NEAREST`, 1 `LINEAR`), and `maxLod` is the
     * `OptionalDouble` as a plain double - negative when Blaze3D did not ask for a limit. They used
     * to be dropped entirely, which clamped every texture and is what turned rain into lines.
     */
    @JvmField val createSampler: MethodHandle =
        handle(
            "create_sampler",
            FunctionDescriptor.of(PTR, PTR, INT, INT, INT, INT, INT, DOUBLE),
        )

    @JvmField val dropSampler: MethodHandle =
        handle("drop_sampler", FunctionDescriptor.ofVoid(PTR))

    /**
     * Hands the terrain pass the game's own block atlas: `(renderer, texture) -> ()`.
     *
     * The texture is one the *game* owns - `TextureAtlas#getTexture` - and the native side keeps a
     * view of it, which is what lets a face whose sprite the game animates be drawn from the atlas the
     * game is already animating, instead of from the frozen copy this renderer packed at startup. It
     * is called beside the sprite registration, on the same stitcher's atlas, because the rectangles
     * and the texture have to be from the same stitch. See `bind_game_block_atlas`.
     */
    @JvmField val bindGameBlockAtlas: MethodHandle =
        handle("bind_game_block_atlas", FunctionDescriptor.ofVoid(PTR, PTR))

    /**
     * Hands the terrain pass the game's **lightmap**: `(renderer, texture) -> ()`.
     *
     * The 16x16 texture Minecraft builds its lighting into, and the one thing the game's own terrain
     * shader samples for it (`sample_lightmap(Sampler2, UV2)`). Handing it over is what makes the
     * terrain's lighting *the game's* - the gamma and brightness options, the time of day, night vision,
     * the darkness effect - rather than a curve written on this side. The game writes into one texture
     * rather than building a new one, so this is called once per texture and not once per frame. See
     * `bind_game_lightmap`.
     */
    @JvmField val bindGameLightmap: MethodHandle =
        handle("bind_game_lightmap", FunctionDescriptor.ofVoid(PTR, PTR))

    @JvmField val compileRenderPipeline: MethodHandle =
        handle("compile_render_pipeline", FunctionDescriptor.of(PTR, PTR, PTR))

    /**
     * Compiles the other depth variant of a pipeline that has already been described.
     *
     * `(renderer, pipeline, depth_state_or_null) -> pipeline`. The shader work lives behind the
     * pipeline this copies from, so all that is left here is the driver's own pipeline creation -
     * which is why the second variant of a pipeline can be left until something draws with it.
     */
    @JvmField val createPipelineVariant: MethodHandle =
        handle("create_pipeline_variant", FunctionDescriptor.of(PTR, PTR, PTR, PTR))

    /**
     * Frees one compiled pipeline variant.
     *
     * `CompiledRenderPipeline` is not `AutoCloseable`, so nothing in Blaze3D calls this; the
     * pipeline cache's own clear and a cleaner do, because each compiled pipeline holds two native
     * pipelines with their bind group layouts and a copy of the descriptor.
     *
     * Null is accepted and ignored: the two depth variants are compiled lazily, so the JVM holds a
     * slot per variant and only one of them may ever have been created.
     */
    @JvmField val dropRenderPipeline: MethodHandle =
        handle("drop_render_pipeline", FunctionDescriptor.ofVoid(PTR))

